WITH agg AS ( SELECT cc.cc_city AS city, sm.sm_type AS ship_mode_type, cp.cp_department AS department, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_ext_sales_price) AS total_sales, AVG(cs.cs_coupon_amt) AS avg_coupon_amt, COUNT(*) AS sales_cnt FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN customer_address ca ON cs.cs_bill_addr_sk = ca.ca_address_sk WHERE cs.cs_sold_date_sk BETWEEN 20000101 AND 20001231 AND sm.sm_type IN ('AIR', 'GROUND') AND cc.cc_city IN ('Greenwood', 'Pleasant Grove') GROUP BY cc.cc_city, sm.sm_type, cp.cp_department HAVING SUM(cs.cs_net_profit) > 10000 ) SELECT city, ship_mode_type, department, total_net_profit, total_sales, avg_coupon_amt, sales_cnt, RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM agg ORDER BY total_net_profit DESC LIMIT 20
